p=json.load(open(sys.argv[1])); assert p.get('schema')=='NOVA_DEPLOY_POLICY_V1'; assert p.get('active_session_gate',{}).get('fatal_on_timeout') is True; assert p.get('global_image_prune') is False
print('DEPLOY_POLICY=PASS active_ws_gate=fatal global_prune=false')
